"""Integer ranges.

A range is a tuple ``(start, end)`` of two ``int``s and stands for every
integer from ``start`` to ``end``, both included. ``(3, 3)`` holds one
integer. ``(5, 2)`` is not a range.
"""


def _validate(ranges):
    """Raise ``ValueError`` if any range has start > end. Return a list of
    the ranges as plain tuples, without changing the input."""
    out = []
    for r in ranges:
        start, end = r
        start = int(start)
        end = int(end)
        if start > end:
            raise ValueError("invalid range: (%r, %r)" % (start, end))
        out.append((start, end))
    return out


def merge(ranges):
    """Join overlapping and neighbouring closed integer ranges. See TASK.md."""
    rs = _validate(ranges)
    rs = sorted(rs, key=lambda r: (r[0], r[1]))
    result = []
    for start, end in rs:
        if result and start <= result[-1][1] + 1:
            # Overlaps or sits right next to the last kept range.
            lo, hi = result[-1]
            result[-1] = (lo, max(hi, end))
        else:
            result.append((start, end))
    return result


def subtract(ranges, holes):
    """The integers in `ranges` that are not in `holes`, as merged ranges."""
    rs = merge(_validate(ranges))
    hs = merge(_validate(holes))

    result = []
    for r_start, r_end in rs:
        # The portion of the current range still not covered by any hole.
        cur_start = r_start
        cur_end = r_end
        for h_start, h_end in hs:
            if h_end < cur_start or h_start > cur_end:
                # No overlap with what remains.
                continue
            # Hole overlaps the remainder.
            if h_start > cur_start:
                result.append((cur_start, h_start - 1))
            cur_start = h_end + 1
            if cur_start > cur_end:
                break
        if cur_start <= cur_end:
            result.append((cur_start, cur_end))

    # The pieces are already sorted by start and non-overlapping, but merging
    # guarantees a canonical form identical to merge()'s output.
    return merge(result)


def count(ranges):
    """How many distinct integers the ranges hold."""
    total = 0
    for start, end in merge(ranges):
        total += end - start + 1
    return total
